package com.witchersbestiary.sorcery;
import java.util.UUID;import net.minecraft.network.*;import net.minecraft.network.codec.PacketCodec;import net.minecraft.network.packet.CustomPayload;import net.minecraft.util.Identifier;import net.fabricmc.fabric.api.networking.v1.*;
public final class SorceryPackets {
 public record Intent(UUID session,long sequence,int action) implements CustomPayload {public static final Id<Intent> ID=new Id<>(Identifier.of("witchersbestiary:sorcery_intent"));public static final PacketCodec<RegistryByteBuf,Intent> CODEC=PacketCodec.of((p,b)->{b.writeUuid(p.session);b.writeLong(p.sequence);b.writeVarInt(p.action);},b->new Intent(b.readUuid(),b.readLong(),b.readVarInt()));public Id<Intent> getId(){return ID;}}
 public record View(UUID session,boolean learned,int cooldown) implements CustomPayload {public static final Id<View> ID=new Id<>(Identifier.of("witchersbestiary:sorcery_view"));public static final PacketCodec<RegistryByteBuf,View> CODEC=PacketCodec.of((p,b)->{b.writeUuid(p.session);b.writeBoolean(p.learned);b.writeVarInt(p.cooldown);},b->new View(b.readUuid(),b.readBoolean(),b.readVarInt()));public Id<View> getId(){return ID;}}
 public record Effect(int entity,int ticks) implements CustomPayload {public static final Id<Effect> ID=new Id<>(Identifier.of("witchersbestiary:icy_grasp"));public static final PacketCodec<RegistryByteBuf,Effect> CODEC=PacketCodec.of((p,b)->{b.writeVarInt(p.entity);b.writeVarInt(p.ticks);},b->new Effect(b.readVarInt(),b.readVarInt()));public Id<Effect> getId(){return ID;}}
 public static void initialize(){PayloadTypeRegistry.playC2S().register(Intent.ID,Intent.CODEC);PayloadTypeRegistry.playS2C().register(View.ID,View.CODEC);PayloadTypeRegistry.playS2C().register(Effect.ID,Effect.CODEC);ServerPlayNetworking.registerGlobalReceiver(Intent.ID,(p,c)->c.server().execute(()->Sorcery.intent(c.player(),p)));}
}
